#!/usr/bin/env node
/**
 * Hivory Design System — bundle + manifest builder (added at v4.1).
 *
 * Regenerates `_ds_bundle.js` (format 3) and `_ds_manifest.json` from the
 * sources of truth: `components/&#42;&#42;/&#42;.jsx`, `tokens/&#42;.css`, the `@dsCard`
 * directives in guideline/component cards, and `@template` directives.
 *
 * Historically both files were generated by external host tooling; this script
 * reproduces the format so the repo can rebuild itself after hand edits
 * (`sourceHashes` = sha256(file)[:12], verified against the host's output).
 *
 * Usage: node scripts/build-bundle.mjs
 */

import { readFileSync, writeFileSync, readdirSync, statSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { join } from 'node:path';
import { transformSync } from 'esbuild';

const NAMESPACE = 'HivoryDesignSystem_354905';

// ─── collect component sources (alphabetical by path — the format's order) ───
const walk = (dir, out = []) => {
  for (const name of readdirSync(dir).sort()) {
    const p = join(dir, name);
    if (statSync(p).isDirectory()) walk(p, out);
    else if (p.endsWith('.jsx')) out.push(p);
  }
  return out;
};
const sources = walk('components');

const componentsMeta = [];
const sourceHashes = {};
const blocks = [];
const allExports = [];

for (const path of sources) {
  const raw = readFileSync(path, 'utf8');
  sourceHashes[path] = createHash('sha256').update(raw).digest('hex').slice(0, 12);

  // collect export names in declaration order; strip `export ` for the IIFE scope
  const names = [...raw.matchAll(/^export\s+(?:function|const|let|class)\s+([A-Za-z_$][\w$]*)/gm)].map((m) => m[1]);
  // The bundle supplies React as a global and wraps each source in an IIFE, where an
  // import statement is a syntax error. Sources carry a real `import * as React` so they
  // work as ES modules (SSR, bundlers); strip it here.
  const stripped = raw
    .replace(/^import\s+\*\s+as\s+React\s+from\s+'react';\n/gm, '')
    .replace(/^export\s+(function|const|let|class)\s+/gm, '$1 ');

  const { code } = transformSync(stripped, {
    loader: 'jsx',
    jsx: 'transform',
    jsxFactory: 'React.createElement',
    jsxFragment: 'React.Fragment',
    target: 'esnext',
    charset: 'utf8',
  });

  for (const n of names) {
    componentsMeta.push({ name: n, sourcePath: path });
    allExports.push(n);
  }
  blocks.push(
    `// ${path}\n` +
    `try { (() => {\n${code.trimEnd()}\n` +
    `Object.assign(__ds_scope, { ${names.join(', ')} });\n` +
    `})(); } catch (e) { __ds_ns.__errors.push({ path: ${JSON.stringify(path)}, error: String((e && e.message) || e) }); }`
  );
}

// ─── bundle ──────────────────────────────────────────────────────────────────
const header = {
  format: 3,
  namespace: NAMESPACE,
  components: componentsMeta,
  sourceHashes,
  inlinedExternals: [],
  unexposedExports: [],
};
const bundle =
  `/* @ds-bundle: ${JSON.stringify(header)} */\n\n` +
  `(() => {\n\n` +
  `const __ds_ns = (window.${NAMESPACE} = window.${NAMESPACE} || {});\n\n` +
  `const __ds_scope = {};\n\n` +
  `(__ds_ns.__errors = __ds_ns.__errors || []);\n\n` +
  blocks.join('\n\n') + '\n\n' +
  allExports.map((n) => `__ds_ns.${n} = __ds_scope.${n};`).join('\n\n') + '\n\n' +
  `})();\n`;
writeFileSync('_ds_bundle.js', bundle);

// ─── tokens (from tokens/*.css) ──────────────────────────────────────────────
const tokenFiles = ['tokens/fonts.css', 'tokens/colors.css', 'tokens/layout.css', 'tokens/typography.css', 'tokens/brands/meaning.css'];
const tokens = [];
for (const file of tokenFiles) {
  const css = readFileSync(file, 'utf8');
  for (const m of css.matchAll(/^\s*(--[\w-]+)\s*:\s*([^;]+);([^\n]*)/gm)) {
    const [, name, value, trail] = m;
    const kindNote = trail.match(/@kind\s+(\w+)/);
    let kind;
    if (kindNote) kind = kindNote[1];
    else if (/^(#|rgba?\(|oklch\()/i.test(value.trim()) || /gradient/.test(value)) kind = 'color';
    else if (name.startsWith('--radius')) kind = 'radius';
    else if (name.startsWith('--space')) kind = 'spacing';
    else if (name.startsWith('--shadow') || name.startsWith('--scrim')) kind = 'shadow';
    else if (/^--(font|text|weight|leading|tracking)/.test(name)) kind = 'font';
    else if (/^var\(--(ink|green|teal|amber|red|black|white)/.test(value.trim())) kind = 'color';
    else kind = 'other';
    tokens.push({ name, value: value.trim(), kind, definedIn: file });
  }
}

// ─── cards (from @dsCard directives) ─────────────────────────────────────────
const cardFiles = [
  ...readdirSync('guidelines').sort().filter((f) => f.endsWith('.html')).map((f) => `guidelines/${f}`),
  ...readdirSync('components').sort().flatMap((d) => {
    const p = `components/${d}/card.html`;
    try { statSync(p); return [p]; } catch { return []; }
  }),
];
const cards = [];
for (const path of cardFiles) {
  const line = readFileSync(path, 'utf8').split('\n', 1)[0];
  const dir = line.match(/@dsCard\s+(.*?)-->/);
  if (!dir) continue;
  const attrs = Object.fromEntries([...dir[1].matchAll(/(\w+)="([^"]*)"/g)].map((m) => [m[1], m[2]]));
  cards.push({ path, group: attrs.group, viewport: attrs.viewport, subtitle: attrs.subtitle, name: attrs.name });
}

// ─── templates (from @template directives in templates/*/*.dc.html) ──────────
const templates = [];
for (const d of readdirSync('templates').sort()) {
  let entries;
  try { entries = readdirSync(`templates/${d}`); } catch { continue; }
  const entry = entries.find((f) => f.endsWith('.dc.html')) || (entries.includes('index.html') ? 'index.html' : null);
  if (!entry) continue;
  const entryPath = `templates/${d}/${entry}`;
  const src = readFileSync(entryPath, 'utf8');
  const tm = src.match(/@template\s+name="([^"]*)"\s+description="([^"]*)"/);
  templates.push({
    name: tm ? tm[1] : d,
    description: tm ? tm[2] : '',
    folder: `templates/${d}`,
    entryPath,
  });
}

// ─── brand fonts (families named in --font-* tokens) ─────────────────────────
const brandFonts = [];
for (const t of tokens) {
  if (!t.name.startsWith('--font')) continue;
  const fam = t.value.match(/^["']([^"']+)["']/);
  if (fam && !brandFonts.some((b) => b.family === fam[1])) {
    brandFonts.push({ family: fam[1], status: 'ok', tokens: [t.name], path: t.definedIn });
  } else if (fam) {
    brandFonts.find((b) => b.family === fam[1]).tokens.push(t.name);
  }
}

const prev = JSON.parse(readFileSync('_ds_manifest.json', 'utf8'));
const manifest = {
  namespace: NAMESPACE,
  components: componentsMeta,
  startingPoints: prev.startingPoints || [],
  cards,
  templates,
  globalCssPaths: prev.globalCssPaths,
  tokens,
  themes: prev.themes,
  fonts: prev.fonts || [],
  brandFonts,
  source: prev.source,
};
writeFileSync('_ds_manifest.json', JSON.stringify(manifest));

console.log(`bundle: ${sources.length} files, ${allExports.length} exports`);
console.log(`manifest: ${cards.length} cards, ${tokens.length} tokens, ${templates.length} templates`);
